const $=id=>document.getElementById(id);
const state={instrument:false,zoom:false,yaw:0,pitch:-.055,pos:new THREE.Vector3(.32,0,1.4),records:{},plots:{P1:{x:0,z:0}},selected:'P2',target:null,started:false};
