const sun=new THREE.DirectionalLight('#ffe4b1',3.6);sun.position.set(-65,65,35);sun.castShadow=true;sun.shadow.mapSize.set(desktopDetail?2048:1024,desktopDetail?2048:1024);Object.assign(sun.shadow.camera,{left:-110,right:110,top:110,bottom:-110,near:1,far:300});sun.shadow.normalBias=.045;sun.shadow.bias=-.0002;sun.target.position.set(20,0,-20);scene.add(sun,sun.target);
