function label(text,color='#fff1ce'){const c=document.createElement('canvas');c.width=256;c.height=96;const cx=c.getContext('2d');cx.fillStyle='#17362ce6';cx.beginPath();cx.roundRect(10,12,236,72,18);cx.fill();cx.strokeStyle='#ffffff70';cx.stroke();cx.fillStyle=color;cx.textAlign='center';cx.font='bold 43px system-ui';cx.fillText(text,128,65);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),depthTest:true,sizeAttenuation:false}));sprite.scale.set(2.8,1.05,1);return sprite;}
const sLabel=label('P1');sLabel.position.set(0,stationY+2.9,0);scene.add(sLabel);
const targets=[];for(const p of corners.slice(1)){const y=terrain(p.x,p.z);for(let i=0;i<6;i++)mesh(new THREE.CylinderGeometry(.075,.075,.4,8),i%2?white:red,p.x,y+.2+i*.4,p.z);mesh(new THREE.BoxGeometry(.43,.43,.13),yellow,p.x,y+2.3,p.z);const prism=mesh(new THREE.OctahedronGeometry(.18),new THREE.MeshStandardMaterial({color:'#b7e2e5',metalness:.75,roughness:.15}),p.x,y+2.3,p.z+.08);prism.rotation.z=Math.PI/4;const l=label(p.id);l.position.set(p.x,y+3.2,p.z);scene.add(l);targets.push({...p,aim:new THREE.Vector3(p.x,y+2.3,p.z),label:l});const flag=mesh(new THREE.PlaneGeometry(.6,.32),new THREE.MeshStandardMaterial({color:'#e8a057',side:THREE.DoubleSide}),p.x+.3,y+1.3,p.z);flag.rotation.y=.3;}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);drawMini();if($('notebookDialog').open)drawPlot();}addEventListener('resize',resize);
function setInstrument(value){state.instrument=value;$('game').classList.toggle('instrument',value);state.zoom=false;camera.fov=value?42:65;camera.updateProjectionMatrix();if(value){state.pos.set(0,0,0);state.yaw=0;state.pitch=Math.atan2(targets[0].aim.y-(stationY+1.75),38);toast('P2 sets your north reference. Aim at its prism and record.');}else{state.pos.set(.32,0,1.4);toast('Walk the site. Return to P1 to take measurements.');}$('scope').hidden=!value;$('crosshair').hidden=value;$('exitInstrument').hidden=!value;$('zoomBtn').hidden=!value;$('joystick').style.visibility=value?'hidden':'';$('zoomBtn').textContent='Zoom 1×';$('stationLabel').textContent=value?'STATION P1 · NORTH REFERENCE':'ON FOOT';instrument.visible=!value;updateUI();}
function record(){if(!state.target){toast('Aim the crosshair at the center of a survey prism.');return;}const p=state.target,r=reading(p);state.records[p.id]={angle:Number(r.angle.toFixed(2)),distance:Number(r.distance.toFixed(2))};toast(`${p.id} recorded · ${r.angle.toFixed(2)}° / ${r.distance.toFixed(2)} m`);state.selected=corners.slice(1).find(p=>state.records[p.id]&&!state.plots[p.id])?.id||p.id;updateUI();drawMini();}
function mainAction(){if(state.instrument)record();else if(Math.hypot(state.pos.x,state.pos.z)<10)setInstrument(true);else toast('Walk back to the glowing P1 station to set up.');}
function updateUI(){const n=Object.keys(state.records).length;$('count').textContent=`${n} of 4 corners measured`;$('noteBadge').textContent=n;$('progressFill').style.width=`${n*25}%`;$('objective').textContent=n===4?'All corners recorded. Open your notebook and plot the boundary.':state.instrument?'Sight each prism, then record its angle and distance.':'Set up your instrument at the glowing P1 station.';$('mainAction').textContent=state.instrument?'Record point':'Set up at P1';$('mainAction').disabled=state.instrument&&!state.target;}
function openNotebook(){keys.clear();stick={x:0,y:0};renderNotes();$('notebookDialog').showModal();drawPlot();}
$('mainAction').onclick=mainAction;$('exitInstrument').onclick=()=>setInstrument(false);$('zoomBtn').onclick=()=>{state.zoom=!state.zoom;camera.fov=state.zoom?18:42;camera.updateProjectionMatrix();$('zoomBtn').textContent=state.zoom?'Zoom 3×':'Zoom 1×';};$('miniButton').onclick=openNotebook;$('notebookBtn').onclick=openNotebook;$('helpBtn').onclick=()=>{$('helpDialog').showModal();keys.clear();};$('startBtn').onclick=()=>{$('helpDialog').close();state.started=true;toast('Welcome. Set up at P1 when you’re ready.');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('fullBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Turn your phone sideways for a wider field view.');}catch{toast('Fullscreen is unavailable here. Try landscape orientation.');}};
function modalOpen(){return $('notebookDialog').open||$('helpDialog').open;}
addEventListener('keydown',e=>{if(modalOpen())return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e','m',' '].includes(k))e.preventDefault();keys.add(k);if(!e.repeat){if(k==='e'||k===' ')mainAction();if(k==='m')openNotebook();}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();stick={x:0,y:0};drag=null;$('stick').style.transform='';});
const view=renderer.domElement;view.addEventListener('pointerdown',e=>{if(modalOpen())return;view.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY};});view.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||modalOpen())return;const f=state.zoom?.0013:state.instrument?.0025:.004;state.yaw+=(e.clientX-drag.x)*f;state.pitch=THREE.MathUtils.clamp(state.pitch-(e.clientY-drag.y)*f,-1.1,.9);drag.x=e.clientX;drag.y=e.clientY;});function stopDrag(e){if(drag?.id===e.pointerId)drag=null;}view.addEventListener('pointerup',stopDrag);view.addEventListener('pointercancel',stopDrag);
const joy=$('joystick');let joyId=null;function moveJoy(e){const r=joy.getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/36,y=(e.clientY-r.top-r.height/2)/36;const len=Math.hypot(x,y);if(len>1){x/=len;y/=len;}stick={x,y};$('stick').style.transform=`translate(${x*29}px,${y*29}px)`;}joy.addEventListener('pointerdown',e=>{joyId=e.pointerId;joy.setPointerCapture(e.pointerId);moveJoy(e);});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyId)moveJoy(e);});function endJoy(e){if(e.pointerId!==joyId)return;joyId=null;stick={x:0,y:0};$('stick').style.transform='';}joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);
function tick(time){requestAnimationFrame(tick);const dt=Math.min((time-last)/1000,.04);last=time;if(!modalOpen()){if(keys.has('arrowleft'))state.yaw-=dt*(state.zoom?.35:.9);if(keys.has('arrowright'))state.yaw+=dt*(state.zoom?.35:.9);if(keys.has('arrowup'))state.pitch=Math.min(.9,state.pitch+dt*.5);if(keys.has('arrowdown'))state.pitch=Math.max(-1.1,state.pitch-dt*.5);if(!state.instrument){let forward=(keys.has('w')?1:0)-(keys.has('s')?1:0)-stick.y,side=(keys.has('d')?1:0)-(keys.has('a')?1:0)+stick.x;const n=Math.max(1,Math.hypot(forward,side));forward/=n;side/=n;state.pos.x+=dt*8*(Math.sin(state.yaw)*forward+Math.cos(state.yaw)*side);state.pos.z+=dt*8*(-Math.cos(state.yaw)*forward+Math.sin(state.yaw)*side);state.pos.x=THREE.MathUtils.clamp(state.pos.x,-70,115);state.pos.z=THREE.MathUtils.clamp(state.pos.z,-110,65);}}
camera.position.set(state.pos.x,terrain(state.pos.x,state.pos.z)+1.75,state.pos.z);camera.rotation.set(state.pitch,-state.yaw,0,'YXZ');camera.updateMatrixWorld();const labelWidth=2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*54/innerHeight;for(const marker of [sLabel,...targets.map(t=>t.label)])marker.scale.set(labelWidth,labelWidth*.375,1);sLabel.visible=!state.instrument&&camera.position.distanceTo(sLabel.position)>4;const direction=new THREE.Vector3();camera.getWorldDirection(direction);let best=null,bestAngle=.045;for(const p of targets){const dir=p.aim.clone().sub(camera.position).normalize();const a=direction.angleTo(dir);if(a<bestAngle){best=p;bestAngle=a;}}
state.target=state.instrument?best:null;const h=wrap(state.yaw*180/Math.PI);$('heading').textContent=`${h.toFixed(0).padStart(3,'0')}°`;$('angle').textContent=state.instrument?`${(state.target?reading(state.target).angle:h).toFixed(2)}°`:'—';$('distance').textContent=state.target?`${reading(state.target).distance.toFixed(2)} m`:'—';$('targetName').textContent=state.target?state.target.id:state.instrument?'Aim at a pole':'P1 station';$('mainAction').disabled=state.instrument&&!state.target;$('targetLabel').textContent=state.target?`${state.target.id} · ${state.records[state.target.id]?'Recorded ✓':'Prism locked'}`:state.instrument?'Drag to sight a prism':Math.hypot(state.pos.x,state.pos.z)<10?'P1 · Ready to set up':'Explore · Return to P1 to survey';$('targetLabel').style.borderColor=state.target?'#efbc69':'#b7d3ae30';ring.material.opacity=.7+Math.sin(time*.002)*.3;ring.material.transparent=true;renderer.render(scene,camera);if(Math.floor(time/150)!==Math.floor((time-dt*1000)/150))drawMini();}
requestAnimationFrame(tick);
// The field book uses a north-up, metric plotting surface. World -Z is north.
const bounds={xmin:-15,xmax:80,zmin:-70,zmax:30};
function mapProject(p,w,h,pad=35){const s=Math.min((w-pad*2)/95,(h-pad*2)/100);return {x:pad+(p.x-bounds.xmin)*s,y:pad+(p.z-bounds.zmin)*s,s};}
function mapUnproject(x,y,w,h,pad=35){const s=mapProject({x:0,z:0},w,h,pad).s;return {x:(x-pad)/s+bounds.xmin,z:(y-pad)/s+bounds.zmin};}
function line(ctx,a,b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
function baseMap(canvas,mini=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=mini?13:42;ctx.clearRect(0,0,w,h);ctx.fillStyle='#ececdb';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#b9c5ac';ctx.lineWidth=mini?.5:1;for(let x=-10;x<=80;x+=10)line(ctx,mapProject({x,z:-70},w,h,pad),mapProject({x,z:30},w,h,pad));for(let z=-70;z<=30;z+=10)line(ctx,mapProject({x:-15,z},w,h,pad),mapProject({x:80,z},w,h,pad));ctx.fillStyle='#536854';ctx.font=`${mini?9:15}px system-ui`;ctx.textAlign='left';ctx.fillText('N',w-25,mini?20:32);ctx.beginPath();ctx.moveTo(w-20,mini?24:40);ctx.lineTo(w-25,mini?37:64);ctx.lineTo(w-20,mini?33:57);ctx.lineTo(w-15,mini?37:64);ctx.closePath();ctx.fill();const scale=mapProject({x:0,z:0},w,h,pad).s;ctx.strokeStyle='#354d3e';ctx.lineWidth=2;line(ctx,{x:pad,y:h-17},{x:pad+20*scale,y:h-17});line(ctx,{x:pad,y:h-21},{x:pad,y:h-13});line(ctx,{x:pad+20*scale,y:h-21},{x:pad+20*scale,y:h-13});ctx.font=`${mini?8:13}px system-ui`;ctx.fillText('0',pad,h-25);ctx.fillText('20 m',pad+20*scale-15,h-25);return {ctx,w,h,pad};}
function dot(ctx,q,text,mini=false,color='#254d3e'){ctx.fillStyle=color;ctx.beginPath();ctx.arc(q.x,q.y,mini?3:6,0,Math.PI*2);ctx.fill();ctx.font=`${mini?10:17}px system-ui`;ctx.fillText(text,q.x+9,q.y-8);}
function drawMini(){const {ctx,w,h,pad}=baseMap($('miniMap'),true);for(const p of corners){const q=mapProject(p,w,h,pad);dot(ctx,q,p.id,true,p.id==='P1'||state.records[p.id]?'#365b3d':'#bb8743');}const pos=mapProject(state.pos,w,h,pad);ctx.save();ctx.translate(pos.x,pos.y);ctx.rotate(state.yaw);ctx.fillStyle='#cb6847';ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(-4,5);ctx.lineTo(4,5);ctx.closePath();ctx.fill();ctx.restore();}
function renderNotes(){$('noteList').replaceChildren();for(const p of corners.slice(1)){const r=state.records[p.id],b=document.createElement('button');b.className='note-row'+(state.selected===p.id?' active':'');b.disabled=!r;b.innerHTML=`<b>${p.id}</b><span>${r?r.angle.toFixed(2)+'°':'Not sighted'}</span><span>${r?r.distance.toFixed(2)+' m':'—'}</span><span>${state.plots[p.id]?'✓':''}</span>`;b.onclick=()=>{state.selected=p.id;$('plotAngle').value='';$('plotDistance').value='';renderNotes();drawPlot();};$('noteList').appendChild(b);}$('plotTitle').textContent=`Plot ${state.selected}`;const enabled=!!state.records[state.selected];$('placeBtn').disabled=!enabled;$('plotAngle').disabled=!enabled;$('plotDistance').disabled=!enabled;$('plotStatus').textContent=enabled?`${state.selected} selected · Use its field notes to place it on the map.`:'Measure a corner from P1, then return to plot it.';$('mapDate').textContent=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function drawPlot(){const {ctx,w,h,pad}=baseMap($('plotMap'));const plotted=corners.filter(p=>state.plots[p.id]);ctx.strokeStyle='#466a54';ctx.lineWidth=2;ctx.setLineDash([7,5]);for(let i=1;i<corners.length;i++){const a=state.plots[corners[i-1].id],b=state.plots[corners[i].id];if(a&&b)line(ctx,mapProject(a,w,h,pad),mapProject(b,w,h,pad));}if(plotted.length===5)line(ctx,mapProject(state.plots.P5,w,h,pad),mapProject(state.plots.P1,w,h,pad));ctx.setLineDash([]);for(const p of plotted)dot(ctx,mapProject(state.plots[p.id],w,h,pad),p.id,false,p.id===state.selected?'#bf7432':'#284e3a');if(state.records[state.selected]){const r=Number($('plotAngle').value),d=Number($('plotDistance').value);if($('plotAngle').value!==''&&Number.isFinite(r)&&Number.isFinite(d)&&d>0&&d<=120){const q=mapProject(fromReading(r,d),w,h,pad),o=mapProject({x:0,z:0},w,h,pad);ctx.strokeStyle='#c2975b';ctx.setLineDash([4,5]);line(ctx,o,q);ctx.setLineDash([]);ctx.beginPath();ctx.arc(q.x,q.y,9,0,Math.PI*2);ctx.stroke();}}}
function placePoint(p){if(!state.records[state.selected])return;state.plots[state.selected]={x:p.x,z:p.z};$('result').textContent='';renderNotes();drawPlot();drawMini();$('plotStatus').textContent=`${state.selected} placed. Select another recorded corner, or check your survey.`;}
$('placeBtn').onclick=()=>{const a=Number($('plotAngle').value),d=Number($('plotDistance').value);if($('plotAngle').value===''||$('plotDistance').value===''||!Number.isFinite(a)||!Number.isFinite(d)||a<0||a>=360||d<=0||d>120){$('plotStatus').textContent='Enter an angle from 0 to under 360° and a distance above 0, up to 120 m.';return;}const p=fromReading(a,d);if(p.x<bounds.xmin||p.x>bounds.xmax||p.z<bounds.zmin||p.z>bounds.zmax){$('plotStatus').textContent='That point falls outside this map. Check your angle and distance.';return;}placePoint(p);};for(const id of ['plotAngle','plotDistance'])$(id).addEventListener('input',drawPlot);
$('plotMap').addEventListener('pointerdown',e=>{if(!state.records[state.selected]){$('plotStatus').textContent='Record this corner at P1 before plotting it.';return;}const c=$('plotMap'),r=c.getBoundingClientRect(),p=mapUnproject((e.clientX-r.left)/r.width*c.width,(e.clientY-r.top)/r.height*c.height,c.width,c.height,42);if(p.x<bounds.xmin||p.x>bounds.xmax||p.z<bounds.zmin||p.z>bounds.zmax)return;placePoint(p);});
$('checkBtn').onclick=()=>{const missing=corners.slice(1).filter(p=>!state.plots[p.id]);if(missing.length){$('result').textContent=`Plot ${missing.map(p=>p.id).join(', ')} before checking the complete boundary.`;return;}const errors=corners.slice(1).map(p=>({id:p.id,e:error(p,state.plots[p.id])})),avg=errors.reduce((s,p)=>s+p.e,0)/4,pass=errors.every(p=>p.e<=1.5),score=Math.max(0,Math.round(100-avg*8));$('result').innerHTML=`<strong>${pass?'Survey complete!':'Keep refining your map'} · ${score}/100</strong><br>Average point error: ${avg.toFixed(2)} m. Practice target: every corner within 1.5 m.<br>${errors.map(p=>p.id+': '+p.e.toFixed(2)+' m').join(' · ')}<br>Your plotted area: ${area(corners.map(p=>state.plots[p.id])).toFixed(0)} m².<br>${pass?'Nice work. You turned field observations into a boundary map.':'Select a corner and use its recorded angle and distance to reposition it.'}`;};
