if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'open_survey_notebook',description:'Open the field notebook and return recorded survey observations and plotted points.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters are accepted.');if($('helpDialog').open)$('helpDialog').close();if(!$('notebookDialog').open)openNotebook();return {records:state.records,plots:state.plots};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
